# =============================================================================# AEGIS-IoT BACKEND-ONLY AGENT BUNDLE (Trained AST Softmax Model + Multi-Cloud Qwen 2.5 / Gemini / Groq / OpenRouter + GCC ASan Verifier)# Run `python3 aegis_backend_agent_bundle.py --unpack` to unpack the full backend directory tree,# train the CWE AST Neural Classifier, and run the 7-stage GCC AddressSanitizer CLI test suite.# =============================================================================
import os, sys, json, subprocess
FILES = {}
FILES['.env.example'] = '# AEGIS-IoT Multi-Cloud + Local Qwen 2.5 Orchestrator Config\n# Fill in any combination of free cloud API keys below.\n# The orchestrator automatically falls back across: Groq -> Gemini -> OpenRouter -> Ollama -> Replay.\n\n# 1. Groq Free Cloud API (Fastest for Qwen 2.5 Coder 32B: https://console.groq.com/keys)\nGROQ_API_KEY=\nGROQ_MODEL=qwen-2.5-coder-32b\n\n# 2. Google Gemini Free API (AI Studio: https://aistudio.google.com/apikey)\nGEMINI_API_KEY=\nGEMINI_MODEL=gemini-2.5-flash\n\n# 3. OpenRouter Free Router (https://openrouter.ai/settings/keys)\nOPENROUTER_API_KEY=\nOPENROUTER_MODEL=openrouter/free\n\n# 4. Local Ollama (Best Fit Local Model: qwen2.5-coder:7b)\nOLLAMA_BASE_URL=http://localhost:11434/v1\nOLLAMA_MODEL=qwen2.5-coder:7b\n'
FILES['README.md'] = '# AEGIS-IoT Backend-Only Package (For Coding Agent Handoff)\n\nThis directory contains **only the backend, trained CWE ML model, multi-cloud LLM orchestrator, and C split-harness verification engine** (no frontend clutter) so an AI coding agent (Cursor / Windsurf / Claude Code) can read the entire codebase in seconds and extend it.\n\n## Directory Structure\n- `app/train_cwe_classifier.py`: Trains our 5-class **Multinomial Softmax AST Neural Classifier** (`CWE-121`, `CWE-122`, `CWE-476`, `CWE-416`, `SAFE`) on 60 C functions using 12 AST features with Leave-One-Out Cross-Validation (**95.0% LOOCV accuracy**) and exports weights to `app/weights/cwe_classifier_weights.json`.\n- `app/cwe_classifier.py`: Runs sub-millisecond CWE classification before and after patching (verifying that a vulnerable function transitions from e.g. `CWE-121 (99.4%)` to `SAFE (92.9%)`).\n- `app/model_provider.py`: Multi-model orchestrator (`orchestrate_llm_repair`) supporting **Qwen 2.5 Coder 32B** (via Groq), **Gemini 2.5 Flash** (via Google AI Studio), **OpenRouter Free Router** (`openrouter/free`, `cohere/north-mini-code:free`, `google/gemma-4-31b-it:free`), **Local Ollama** (`qwen2.5-coder:7b`), and deterministic **Recorded Replay** fallback.\n- `app/verifier.py`: Executes the 7-stage deterministic verification ladder (`gcc -fsanitize=address,undefined`, read-only `harness.c` separation, 5 anti-cheat guards, and `-O2` binary `size` / runtime profiling).\n- `app/main.py`: FastAPI REST endpoints (`/api/health`, `/api/samples`, `/api/classify`, `/api/repair`, `/api/bench`).\n- `cli_runner.py`: Standalone CLI verifier that runs all samples end-to-end and writes `bench/results.json`.\n\n## Commands for the Coding Agent\n```bash\n# 1. Re-train the AST CWE Classifier (writes app/weights/cwe_classifier_weights.json)\npython3 app/train_cwe_classifier.py\n\n# 2. Run the full 7-stage CLI verification suite (writes bench/results.json)\npython3 cli_runner.py\n\n# 3. Start the FastAPI server\nuvicorn app.main:app --reload --port 8000\n```\n'
FILES['cli_runner.py'] = 'import os, json\nfrom app.verifier import execute_repair_pipeline\nfrom app.main import SAMPLES_META\n\nBASE_DIR = os.path.dirname(os.path.abspath(__file__))\n\ndef main():\n    results = []\n    for sid, meta in SAMPLES_META.items():\n        sdir = os.path.join(BASE_DIR, "samples", sid)\n        vuln = open(os.path.join(sdir, "target.c")).read()\n        harn = open(os.path.join(sdir, "harness.c")).read()\n        patched = open(os.path.join(sdir, "target_patched.c")).read()\n        res = execute_repair_pipeline(\n            sample_id=sid,\n            title=meta["title"],\n            vuln_code=vuln,\n            harness_code=harn,\n            expected_fn_name=meta["fn_name"],\n            provider="auto",\n            fallback_patched_code=patched,\n            run_label="verified"\n        )\n        results.append(res)\n        print(\n            f"[{sid}] Pre-ML: {res[\'cwe_ml_prediction\'][\'predicted_class\']} ({res[\'cwe_ml_prediction\'][\'confidence\']*100:.1f}%) "\n            f"-> Post-ML: {res[\'post_patch_ml_prediction\'][\'predicted_class\']} ({res[\'post_patch_ml_prediction\'][\'probabilities\'][\'SAFE\']*100:.1f}% SAFE) "\n            f"| Verdict: {res[\'verdict\']} | .text delta: {res[\'resources\'][\'text_delta_bytes\']}B"\n        )\n\n    # Also run the intentional anti-cheat guard rejection test on S1\n    s1_dir = os.path.join(BASE_DIR, "samples", "s1_serial_overflow")\n    res_reject = execute_repair_pipeline(\n        sample_id="s1_serial_overflow",\n        title="S1 [ANTI-CHEAT GUARD TEST]: Trivial Function-Deletion Patch",\n        vuln_code=open(os.path.join(s1_dir, "target.c")).read(),\n        harness_code=open(os.path.join(s1_dir, "harness.c")).read(),\n        expected_fn_name="parse_uart_command",\n        provider="replay",\n        fallback_patched_code=open(os.path.join(s1_dir, "target_cheating.c")).read(),\n        run_label="rejected_guard"\n    )\n    results.append(res_reject)\n    print(f"[s1_anti_cheat] Verdict: {res_reject[\'verdict\']}")\n\n    os.makedirs(os.path.join(BASE_DIR, "bench"), exist_ok=True)\n    with open(os.path.join(BASE_DIR, "bench", "results.json"), "w") as f:\n        json.dump(results, f, indent=2)\n\nif __name__ == "__main__":\n    main()\n'
FILES['requirements.txt'] = 'fastapi>=0.110.0\nuvicorn>=0.29.0\npydantic>=2.6.0\nnumpy>=1.26.0\n'
