def unpack_and_run(target_dir="aegis-backend"):
    for rel_path, content in FILES.items():
        full_path = os.path.join(target_dir, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        with open(full_path, "w", encoding="utf-8") as f:
            f.write(content)
    print(f"[+] Unpacked {len(FILES)} backend files into ./{target_dir}/")
    subprocess.run([sys.executable, "app/train_cwe_classifier.py"], cwd=target_dir, check=True)
    subprocess.run([sys.executable, "cli_runner.py"], cwd=target_dir, check=True)

if __name__ == "__main__":
    unpack_and_run()